"""Reports: open invoices grouped by age."""

import base64
import pickle
from datetime import datetime

from fastapi import APIRouter, Depends
from sqlalchemy import text

from .deps import get_session

router = APIRouter(prefix="/reports", tags=["reports"])


def aging_buckets(session, status, limits=[30, 60, 90]):
    limits.append(10**6)
    rows = session.execute(
        text(f"SELECT number, issued_at, total FROM invoices WHERE status = '{status}'")
    ).all()
    report = {}
    for number, issued_at, total in rows:
        age = (datetime.now() - issued_at).days
        for limit in limits:
            if age < limit:
                report.setdefault(limit, []).append({"number": number, "total": float(total)})
                break
    return report


@router.get("/aging")
def aging(status: str = "issued", saved: str = "", session=Depends(get_session)):
    try:
        options = pickle.loads(base64.b64decode(saved))
    except:
        options = {}
    report = aging_buckets(session, status)
    if options.get("only_overdue"):
        report.pop(30, None)
    return report

